const source = $json.body && typeof $json.body === 'object' ? $json.body : $json;
const contact = source.contact || {};
const account = source.account || source.company || {};
const fullName = (source.fullName || contact.fullName || contact.name || [contact.firstName || source.firstName, contact.lastName || source.lastName].filter(Boolean).join(' ')).toString().trim();
const email = (source.email || contact.email || '').toString().trim().toLowerCase();
const phone = (source.phone || contact.phone || '').toString().trim();
const companyName = (source.companyName || account.name || account.companyName || source.company || '').toString().trim();
const website = (source.website || account.website || '').toString().trim();
const title = (source.title || source.jobTitle || contact.title || contact.jobTitle || '').toString().trim();
const location = (source.location || contact.location || account.location || '').toString().trim();
const contactLinkedin = (source.linkedinUrl || source.linkedInUrl || contact.linkedinUrl || contact.linkedInUrl || '').toString().trim();
const companyLinkedin = (source.companyLinkedinUrl || source.companyLinkedInUrl || account.linkedinUrl || account.linkedInUrl || '').toString().trim();
const errors = [];
if (!email && !phone && !fullName) errors.push('Provide at least one contact identifier: email, phone, or fullName.');
if (!companyName && !website) errors.push('Provide at least one account identifier: companyName or website.');
const normalized = {
  contact: { firstName: source.firstName || contact.firstName || '', lastName: source.lastName || contact.lastName || '', fullName, email, phone, title, location, linkedinUrl: contactLinkedin, type: 'lead' },
  account: { name: companyName, website, linkedinUrl: companyLinkedin, industry: source.industry || account.industry || '', size: source.companySize || account.size || account.companySize || '', location, type: 'Lead' },
  source: { rawLead: source, receivedAt: new Date().toISOString() }
};
const enrichmentPrompt = `Enrich this CRM lead JSON. Return verified or clearly inferred business fields only. Do not create CRM records. Do not invent facts. Use null when unknown.\n\nLead JSON:\n${JSON.stringify(normalized, null, 2)}\n\nReturn strict JSON with this exact shape:\n{\n  "contact": {"firstName": null, "lastName": null, "fullName": null, "email": null, "phone": null, "title": null, "location": null, "linkedinUrl": null},\n  "account": {"name": null, "website": null, "linkedinUrl": null, "industry": null, "size": null, "location": null},\n  "otherRelevantFields": {},\n  "confidence": "high|medium|low",\n  "warnings": []\n}`;
return [{ json: { isValid: errors.length === 0, validationErrors: errors, normalized, enrichmentPrompt } }];

const normalized = $('Validate and Normalize Lead').item.json.normalized;
function pickText(obj) {
  if (typeof obj.response === 'string') return obj.response;
  if (typeof obj.text === 'string') return obj.text;
  if (typeof obj.message === 'string') return obj.message;
  if (typeof obj.output_text === 'string') return obj.output_text;
  const output = obj.output || [];
  for (const entry of output) {
    for (const content of entry.content || []) {
      if (content.text) return content.text;
    }
  }
  if (obj.response && typeof obj.response === 'object') return JSON.stringify(obj.response);
  return JSON.stringify(obj);
}
let raw = pickText($json);
let parsed;
try {
  parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (error) {
  const match = String(raw).match(/\{[\s\S]*\}/);
  parsed = match ? JSON.parse(match[0]) : { warnings: ['OpenAI did not return parseable JSON'], rawOutput: raw };
}
const enriched = {
  contact: { ...normalized.contact, ...(parsed.contact || {}) },
  account: { ...normalized.account, ...(parsed.account || {}) },
  otherRelevantFields: parsed.otherRelevantFields || {},
  confidence: parsed.confidence || 'low',
  warnings: Array.isArray(parsed.warnings) ? parsed.warnings : []
};
return [{ json: { normalized, enriched, openAiRaw: parsed } }];

const previous = $('Parse OpenAI Enrichment').item.json;
function unpack(input) {
  let obj = input;
  if (input.body) obj = input.body;
  if (typeof obj === 'string') {
    const dataLine = obj.split('\n').find(line => line.startsWith('data:'));
    obj = JSON.parse(dataLine ? dataLine.replace(/^data:\s*/, '') : obj);
  }
  const text = obj?.result?.content?.[0]?.text;
  if (typeof text === 'string') { try { obj = JSON.parse(text); } catch { obj = text; } }
  return obj;
}
const payload = unpack($json);
const records = Array.isArray(payload) ? payload : (payload.records || payload.data || payload.items || payload.result || []);
const existingContact = Array.isArray(records) && records.length ? records[0] : null;
return [{ json: { ...previous, contactExists: !!existingContact, existingContact, contactSearchRaw: payload } }];

const previous = $('Parse Contact Search').item.json;
function unpack(input) {
  let obj = input.body || input;
  if (typeof obj === 'string') {
    const dataLine = obj.split('\n').find(line => line.startsWith('data:'));
    obj = JSON.parse(dataLine ? dataLine.replace(/^data:\s*/, '') : obj);
  }
  const text = obj?.result?.content?.[0]?.text;
  if (typeof text === 'string') { try { obj = JSON.parse(text); } catch { obj = text; } }
  return obj;
}
const payload = unpack($json);
const records = Array.isArray(payload) ? payload : (payload.records || payload.data || payload.items || payload.result || []);
const account = Array.isArray(records) && records.length ? records[0] : null;
return [{ json: { ...previous, accountExists: !!account, account, accountSearchRaw: payload } }];

const previous = $('Parse Account Search').item.json;
function unpack(input) {
  let obj = input.body || input;
  if (typeof obj === 'string') {
    const dataLine = obj.split('\n').find(line => line.startsWith('data:'));
    obj = JSON.parse(dataLine ? dataLine.replace(/^data:\s*/, '') : obj);
  }
  const text = obj?.result?.content?.[0]?.text;
  if (typeof text === 'string') { try { obj = JSON.parse(text); } catch { obj = text; } }
  return obj;
}
const payload = unpack($json);
const account = payload.record || payload.data || payload.item || payload.result || payload;
return [{ json: { ...previous, accountExists: false, account, accountCreateRaw: payload } }];

const account = $json.account || {};
const accountId = account.id || account._id || account.account_id || null;
const contact = $json.enriched.contact || {};
const data = {
  firstName: contact.firstName || $json.normalized.contact.firstName || '',
  lastName: contact.lastName || $json.normalized.contact.lastName || '',
  name: contact.fullName || $json.normalized.contact.fullName || [contact.firstName, contact.lastName].filter(Boolean).join(' '),
  email: contact.email || $json.normalized.contact.email || null,
  phone: contact.phone || $json.normalized.contact.phone || null,
  title: contact.title || null,
  location: contact.location || null,
  linkedinUrl: contact.linkedinUrl || null,
  type: 'lead',
  account: accountId,
  message_additional_info: JSON.stringify({ source: 'website lead form', enrichment: $json.enriched, receivedAt: $json.normalized.source.receivedAt })
};
return [{ json: { ...$json, contactCreatePayload: data } }];
